package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="pricing_audit_logs") public class PricingAuditLog{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="entity_type",nullable=false,length=40) private String entityType;@Column(name="entity_id",nullable=false) private UUID entityId;@Column(nullable=false,length=40) private String action;@Column(nullable=false,length=150) private String actor;@Column(name="actor_role",length=60) private String actorRole;@Column(name="old_value",columnDefinition="TEXT") private String oldValue;@Column(name="new_value",columnDefinition="TEXT") private String newValue;@Column(length=500) private String comments;@Column(name="ip_address",length=64) private String ipAddress;@Column(name="created_at",nullable=false) private Instant createdAt;@PrePersist void create(){createdAt=Instant.now();}public UUID getId(){return id;}public String getEntityType(){return entityType;}public UUID getEntityId(){return entityId;}public String getAction(){return action;}public String getActor(){return actor;}public String getActorRole(){return actorRole;}public String getOldValue(){return oldValue;}public String getNewValue(){return newValue;}public String getComments(){return comments;}public String getIpAddress(){return ipAddress;}public Instant getCreatedAt(){return createdAt;}public void setEntityType(String v){entityType=v;}public void setEntityId(UUID v){entityId=v;}public void setAction(String v){action=v;}public void setActor(String v){actor=v;}public void setActorRole(String v){actorRole=v;}public void setOldValue(String v){oldValue=v;}public void setNewValue(String v){newValue=v;}public void setComments(String v){comments=v;}public void setIpAddress(String v){ipAddress=v;}}
